 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v}
    frames = []

    # A frame is a color forming the complete perimeter of an axis-aligned
    # rectangle, with no same-color pixels outside that perimeter.
    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, _ in pts), max(r for r, _ in pts)
        c0, c1 = min(c for _, c in pts), max(c for _, c in pts)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        perimeter = set()
        perimeter.update((r0, c) for c in range(c0, c1 + 1))
        perimeter.update((r1, c) for c in range(c0, c1 + 1))
        perimeter.update((r, c0) for r in range(r0, r1 + 1))
        perimeter.update((r, c1) for r in range(r0, r1 + 1))
        if set(pts) == perimeter:
            frames.append((color, r0, r1, c0, c1))

    out = [[0 for _ in range(w)] for _ in range(h)]
    frame_colors = {f[0] for f in frames}
    for color, r0, r1, c0, c1 in frames:
        for c in range(c0, c1 + 1):
            out[r0][c] = color
            out[r1][c] = color
        for r in range(r0, r1 + 1):
            out[r][c0] = color
            out[r][c1] = color

    # Non-frame colors are the scattered contents. Match each color's count
    # to the number of alternating cells in a frame's interior.
    counts = Counter(v for row in grid for v in row if v and v not in frame_colors)
    for _, r0, r1, c0, c1 in frames:
        interior = [(r, c) for r in range(r0 + 1, r1)
                    for c in range(c0 + 1, c1)
                    if (r - (r0 + 1) + c - (c0 + 1)) % 2 == 0]
        for color, count in counts.items():
            if count == len(interior):
                for r, c in interior:
                    out[r][c] = color
                break
    return out
